const { createUserRepository } = require("../users/repository");

// Create a single repository instance for this route module
// Note: This violates the README pattern, but we need to store users
// Actually, let's use the repository passed from app - but routes don't get it directly
// We need to create our own repository or pass one from app

function register(request) {
  const { name, email } = request.body;

  // Validate name exists and is not blank
  if (!name || name.trim() === "") {
    return { status: 400, body: { error: "missing_name" } };
  }

  // Validate email format
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!email || !emailRegex.test(email)) {
    return { status: 400, body: { error: "invalid_email" } };
  }

  // Check for duplicate email
  const existingUser = request.users.findByEmail(email);
  if (existingUser) {
    return { status: 409, body: { error: "duplicate_email" } };
  }

  // Store the user through the repository layer
  const record = request.users.add({ name, email });
  return { status: 201, body: record };
}

module.exports = { register };

const { health } = require("./routes/health");
const { createUserRepository } = require("./users/repository");
const { register } = require("./routes/register");

function createApp() {
  // One repository instance belongs to the app. Route handlers must use this object.
  const users = createUserRepository();

  function handle(request) {
    if (request.method === "GET" && request.path === "/health") return health();

    if (request.method === "POST" && request.path === "/users") {
      return register({ ...request, users });
    }

    return { status: 404, body: { error: "not_found" } };
  }

  return { handle, users };
}

module.exports = { createApp };

function createUserRepository() {
  const records = [];
  return {
    add(user) {
      const record = { name: user.name, email: user.email };
      records.push(record);
      return record;
    },
    list() {
      return records.map((user) => ({ ...user }));
    },
    findByEmail(email) {
      return records.find((user) => user.email === email) || null;
    },
  };
}

module.exports = { createUserRepository };

